import { describe, expect, it } from 'vitest'

import fixture from './transfer-estimate.fixture.json'
import { estimateTransfer, formatRemaining } from './transfer-estimate'

describe('estimating the time a transfer has left', () => {
  it('agrees with AMC’s estimate_transfer, run under CPython, on every case', () => {
    // Generated by calling AMC's own function: the boundary at one second,
    // nothing moved yet, an overshoot past the total, an unknown size.
    for (const c of fixture) {
      const ours = estimateTransfer(c.transferred, c.total ?? undefined, c.elapsed)
      expect(ours.bytesPerSecond ?? null, JSON.stringify(c)).toBe(c.rate)
      expect(ours.remainingSeconds ?? null, JSON.stringify(c)).toBe(c.remaining)
    }
  })

  it('covers the cases that decide anything', () => {
    expect(fixture.some((c) => c.rate === null && c.elapsed < 1)).toBe(true)
    expect(fixture.some((c) => c.rate !== null && c.remaining === null)).toBe(true)
    expect(fixture.some((c) => c.remaining === 0 && c.transferred > (c.total ?? 0))).toBe(true)
  })
})

describe('showing it', () => {
  it('stays short, because it sits beside a percentage', () => {
    expect(formatRemaining(0)).toBe('0 s')
    expect(formatRemaining(45)).toBe('45 s')
    expect(formatRemaining(125)).toBe('2:05')
    expect(formatRemaining(3725)).toBe('1:02:05')
  })
})
